from .ranges import parse_range, resolve


def serve(data, range_header=None):
    if range_header is None:
        return 200, {'Content-Length': str(len(data))}, data
    bounds = resolve(parse_range(range_header), len(data))
    if bounds is None:
        return 416, {'Content-Length': '0',
                     'Content-Range': 'bytes */%d' % len(data)}, b''
    start, end = bounds
    body = data[start:end + 1]
    return 206, {'Content-Length': str(len(body)),
                 'Content-Range': 'bytes %d-%d/%d' % (start, end, len(data))}, body
